UPDATE ainer_identity_membership
SET role = #{newRole},
    updated_at = #{updatedAt}
WHERE tenant_id = #{tenantId}
  AND user_id = #{subjectId}
  AND status = 'ACTIVE'

UPDATE ainer_identity_membership
SET role = #{newRole},
    status = 'ACTIVE',
    updated_at = #{updatedAt}
WHERE tenant_id = #{tenantId}
  AND user_id = #{subjectId}
  AND status = #{expectedStatus}
  AND role <> 'OWNER'

